property.value:
let $key := function($e) {
      if ($e/self::VariableAccess or $e/self::FieldAccess[ThisExpression]) then string($e/@Name) else ()
    },
    $lenKey := function($n) {
      if ($n/self::FieldAccess[@Name = 'length'] or $n/self::MethodCall[@MethodName = 'size'][ArgumentList/@Size = 0])
      then $key($n/*[1]) else ()
    },
    $int := function($n) {
      if ($n/self::NumericLiteral[@IntLiteral = true()]) then xs:integer($n/@ValueAsInt) else ()
    },
    $positive := function($g, $k) {
      if ($g/self::InfixExpression[@Operator = ('>', '>=', '==')][$lenKey(*[1]) = $k][*[2][self::NumericLiteral]])
      then (if ($g/@Operator = '>') then $int($g/*[2]) else $int($g/*[2]) - 1)
      else ()
    },
    $negative := function($g, $k) {
      if ($g/self::InfixExpression[@Operator = ('<', '<=')][$lenKey(*[1]) = $k][*[2][self::NumericLiteral]])
      then (if ($g/@Operator = '<') then $int($g/*[2]) - 1 else $int($g/*[2]))
      else if ($g/self::InfixExpression[@Operator = '=='][$lenKey(*[1]) = $k][*[2][self::NumericLiteral][@ValueAsInt = 0]])
      then 0 else ()
    },
    $leaves := function($cond, $sep) {
      ($cond/descendant-or-self::InfixExpression[@Operator = $sep]
          [empty((ancestor::*[not(self::InfixExpression[@Operator = $sep])]) intersect ($cond/descendant-or-self::*))]/*
       | $cond)[not(self::InfixExpression[@Operator = $sep])]
    },
    $under := function($a, $part) { exists($a/ancestor-or-self::* intersect $part) },
    $exits := function($s) {
      exists($s/self::ReturnStatement | $s/self::ThrowStatement
             | $s/self::Block/*[last()][self::ReturnStatement or self::ThrowStatement])
    },
    $mk := function($g, $v) { if (exists($v)) then map { 'n': $g, 'v': $v } else () },
    $guards := function($a, $k) {
      (for $c in $a/ancestor::ConditionalExpression[$under($a, *[2])] | $a/ancestor::IfStatement[$under($a, *[2])]
         | $a/ancestor::InfixExpression[@Operator = '&&'][$under($a, *[2])]
         return for $g in $leaves($c/*[1], '&&') return $mk($g, $positive($g, $k)),
       for $c in $a/ancestor::InfixExpression[@Operator = '||'][$under($a, *[2])]
         return for $g in $leaves($c/*[1], '||') return $mk($g, $negative($g, $k)),
       for $c in $a/ancestor::ConditionalExpression[$under($a, *[3])] | $a/ancestor::IfStatement[$under($a, *[3])]
         return for $g in $leaves($c/*[1], '||') return $mk($g, $negative($g, $k)),
       for $b in $a/ancestor::Block
         return for $c in $b/*[following-sibling::* intersect $a/ancestor::*][self::IfStatement][count(*) = 2][$exits(*[2])]
           return for $g in $leaves($c/*[1], '||') return $mk($g, $negative($g, $k)))
    }
return (
  //ArrayAccess[*[2][self::NumericLiteral][@IntLiteral = true()]]
  | //MethodCall[@MethodName = 'get'][ArgumentList/@Size = 1][ArgumentList/NumericLiteral[@IntLiteral = true()]]
      [*[1][pmd-java:typeIs('java.util.List')]]
)[let $k := $key(*[1]),
      $m := if (self::ArrayAccess) then $int(*[2]) else $int(ArgumentList/*[1]),
      $found := if (exists($k)) then $guards(., $k) else (),
      $scope := ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::Initializer][1],
      $self := .
  return exists($found) and $m > max($found ! .?v)
     and (every $n in $scope//*[$lenKey(.) = $k][. << $self] satisfies exists($found ! .?n/*[1][. is $n]))
     and empty($scope//*[self::VariableAccess or self::FieldAccess][@Name = $k][@AccessType = 'WRITE'])]
